/** The OtpStartDto the API takes. */
class OtpStartDto {
  const OtpStartDto({required this.login, required this.app, this.deviceToken, this.ip, this.userAgent});
  final String login;
  final String app;
  final String? deviceToken;
  final String? ip;
  final String? userAgent;
  Map<String, Object?> toJson() => {
        'login': login,
        'app': app,
        if (deviceToken != null) 'deviceToken': deviceToken,
        if (ip != null) 'ip': ip,
        if (userAgent != null) 'userAgent': userAgent,
      };
}

/** The MobileCodeDto the API takes. */
class MobileCodeDto {
  const MobileCodeDto({required this.challengeId, required this.code, required this.device});
  final String challengeId;
  final String code;
  final MobileCodeDtoDevice device;
  Map<String, Object?> toJson() => {
        'challengeId': challengeId,
        'code': code,
        'device': device.toJson(),
      };
}

